class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> prefix(n, 1);
        vector<int> suffix(n, 1);
        vector<int> ans(n);

        for (int i = 1; i < n; i++) {
            prefix[i] = prefix[i-1] * nums[i-1];
        }

        for (int i = n-2; i >= 0; i--) {
            suffix[i] = suffix[i+1] * nums[i+1];
        }

        for (int i = 0; i < n; i++) {
            ans[i] = prefix[i] * suffix[i];
        }

        return ans;
    }
};

class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(n, 1);

        int prefix = 1;
        for (int i = 0; i < n; i++) {
            ans[i] = prefix;
            prefix *= nums[i];
        }

        int suffix = 1;
        for (int i = n - 1; i >= 0; i--) {
            ans[i] *= suffix;
            suffix *= nums[i];
        }

        return ans;
    }
};

class Solution {
public:
    bool isAnagram(string s, string t) {
        if(s.size() != t.size()) return false;
        vector<int> arr1(256, 0);
        vector<int> arr2(256, 0);
        for(auto i : s) arr1[i]++;
        for(auto i : t) arr2[i]++;
        return arr1 == arr2;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        if (head == NULL || head->next == NULL) return head;
        if(head->next->next == NULL){
            ListNode* temp = head->next;
            head->next->next = head;
            head->next = NULL;
            return temp;
        }
        ListNode* first = head;
        ListNode* second = head->next;
        ListNode* third = second->next;

        while(third != NULL){
            second->next = first;
            first = second;
            second = third;
            third = third->next;
        }
        second->next = first;
        head->next = NULL;
        return second;

    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* middleNode(ListNode* head) {
        ListNode* f = head;
        ListNode* s = head;

        while( f->next != NULL ){
            f = f->next->next;
            s = s->next;
            if(f == NULL){
                break;
            }
        }
        return s;
    }
};

class Solution {
public:
    bool hasCycle(ListNode *head) {
        if (head == NULL || head->next == NULL) return false;

        ListNode* slow = head;
        ListNode* fast = head;

        while (fast != NULL && fast->next != NULL) {
            slow = slow->next;           
            fast = fast->next->next;    

            if (slow == fast) return true;  
        }

        return false;  
    }
};

class Solution {
public:
    bool isValid(string s) {
        stack<char> st;
        for (auto i : s) {
            if (i == '(' || i == '{' || i == '[') {
                st.push(i);
            } else {
                if (st.empty()) return false; 
                if ((i == ')' && st.top() == '(') ||
                    (i == '}' && st.top() == '{') ||
                    (i == ']' && st.top() == '[')) {
                    st.pop();
                } else {
                    return false;  
                }
            }
        }
        return st.empty();  
    }
};

class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        int n1 = nums1.size();
        int n2 = nums2.size();
        stack<int> st;
        vector<int> nxt(n2, -1);
        vector<int> ans(n1, -1);
        st.push(nums2[n2-1]);
        for(int i = n2-2; i>=0; i--){
            while(!st.empty() && st.top() < nums2[i]){
                st.pop();
                if(st.empty()) break;
            }
            if(!st.empty() && nums2[i] < st.top()){
                nxt[i] = st.top();
            }
            st.push(nums2[i]);
        }

        for(int i = 0; i<n1; i++){
            int index = find(nums2.begin(), nums2.end(), nums1[i]) - nums2.begin();
            ans[i] = nxt[index];
        }

        return ans;

    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (root == NULL) return {};

        vector<vector<int>> ans;
        queue<TreeNode*> qu;
        qu.push(root);

        while (!qu.empty()) {
            int size = qu.size();       
            vector<int> level;

            for (int i = 0; i < size; i++) {
                TreeNode* temp = qu.front();
                qu.pop();
                level.push_back(temp->val);

                if (temp->left != NULL) qu.push(temp->left);
                if (temp->right != NULL) qu.push(temp->right);
            }

            ans.push_back(level);
        }

        return ans;
    }
};
